const supportVerified=r=>r?.supportPinsVerified===true||r?.pinsVerified===true;
const presentationVerified=r=>r?.jungle?r.jungle.supportPinsVerified===true&&r.jungle.presentationPinsVerified===true&&r.jungle.presentationReady===true:r?.presentationPinsVerified===true||r?.pinsVerified===true;
import{localWarp}from'./transition.mjs';import{JunglePuzzle,POINTS}from'../student_puzzle_candidate/controller.mjs';import{LayerWalker}from'../student_puzzle_candidate/layer-walker.mjs';import{issueLocalReceipt,verifyLocalReceipt,exportProgress}from'../student_puzzle_candidate/snapshot-receipt.mjs';
export class JungleNativeHost{
 constructor(){this.epoch=0;this.ready=false;this.state=null;this.resources=null;this.held=false;this.busy=false;this.elapsedMs=0;this.paused=false;this.puzzle=null;this.walker=null;this.receipt=null}
 async load(loader){const epoch=++this.epoch;this.ready=false;this.busy=true;this.puzzle?.dispose();this.resources?.dispose?.();this.resources=null;try{const r=await loader();if(epoch!==this.epoch){r?.dispose?.();return{ok:false,reason:'STALE_LOAD'}}if(!supportVerified(r)||!r.safe('jungle-exterior-r7',[768,970],'CLOSED')){r?.dispose?.();throw Error('PIN_OR_INITIAL_SUPPORT')}this.resources=r;this.state={scene:'jungle-exterior-r7',foot:[768,970],facing:'up',interiorState:'CLOSED',layer:'ground',warpLock:true};this.puzzle=new JunglePuzzle({safe:(layer,foot,state)=>r.supports([layer],foot,state),symbolSelection:r.symbolSelection,canOpenGate:ctx=>r.supports([ctx.layer],ctx.foot,'CLOSED')&&r.supports([ctx.layer],ctx.foot,'OPEN')});this.receipt=null;this.walker=null;this.ready=true;return{ok:true}}finally{if(epoch===this.epoch)this.busy=false}}
 cancel(){this.epoch++;this.ready=false;this.busy=false;this.held=true;this.puzzle?.dispose();this.resources?.dispose?.();this.resources=null;this.state=null;this.walker=null;this.receipt=null}
 release(){this.held=false;this.puzzle?.release();if(this.state)this.state=localWarp(this.state,{released:true})}
 context(){return{...this.state,pinsVerified:presentationVerified(this.resources),foot:[...this.state.foot]}}
 nearby(){if(!this.ready||this.state.scene!=='jungle-interior-r2'||this.walker?.transit)return null;return Object.keys(POINTS).find(id=>this.puzzle.check(this.context(),id))??null}
 interact(){if(!this.ready||this.busy||this.paused||this.held)return{ok:false,reason:'LOCKED_OR_RELEASE_REQUIRED'};this.held=true;const next=localWarp(this.state,{pressed:true,pinsVerified:presentationVerified(this.resources)});if(next===this.state){const id=this.nearby();return id?{ok:true,menu:id}:{ok:false,reason:'APPROACH_OR_FACING'}}if(!this.resources.safe(next.scene,next.foot,next.interiorState))return{ok:false,reason:'TARGET_UNSUPPORTED'};this.state={...next,layer:'ground'};this.walker=next.scene==='jungle-interior-r2'?new LayerWalker({foot:next.foot,layer:'ground',supports:(layers,foot)=>this.resources.supports(layers,foot,this.puzzle.snapshot().cOpen?'OPEN':'CLOSED')}):null;return{ok:true,scene:next.scene}}
 puzzleAction(type,id){if(!this.ready||this.busy||this.paused||this.walker?.transit)return{ok:false,reason:'LOCKED_OR_TRANSIT'};const result=this.puzzle.action(type,id,this.context());this.state.interiorState=this.puzzle.snapshot().cOpen?'OPEN':'CLOSED';if(result.ok&&this.puzzle.completion().eligibleForFutureCanonicalValidation&&(!this.receipt||!verifyLocalReceipt(this.receipt,this.puzzle)))this.receipt=issueLocalReceipt(this.puzzle);return result}
 move(dx,dy){if(!this.ready||this.busy||this.paused||!Number.isInteger(dx)||!Number.isInteger(dy)||(dx&&dy)||Math.abs(dx||dy)>240)return 0;const s=this.state;if(s.scene==='jungle-interior-r2'){const n=this.walker.move(dx,dy);s.foot=[...this.walker.foot];s.facing=this.walker.facing;s.layer=this.walker.layer;return n}if(dx)s.facing=dx>0?'right':'left';if(dy)s.facing=dy>0?'down':'up';let n=0;for(;n<Math.abs(dx||dy);n++){const p=[s.foot[0]+Math.sign(dx),s.foot[1]+Math.sign(dy)];if(!this.resources.safe(s.scene,p,s.interiorState))break;s.foot=p}return n}
 tick(dt){if(!this.ready||this.paused||!Number.isFinite(dt)||dt<0||dt>250)return false;this.elapsedMs+=dt;return true}
 progressSnapshot(){return exportProgress(this.puzzle)}
}
